            public boolean openFolderAfterComplete() { return false; }
        }), activities, paramCommands, imports);
    }

    /**
     * B5-1：带导入编排协调器的完整构造（GUI 传入共享 FX 派发器与确认卡实现的协调器；
     * 无头调用方可注入小配额/延迟派发器的协调器复现「每轮打满」）。
     */
    public InProcessUiport(WorkspaceModel model, Confirmer confirmer, ExtractionPlanService plans,
                          WorkspaceActivityService activities, WorkspaceParamCommandService paramCommands,
                          WorkspaceImportCoordinator imports) {
        this(model, confirmer, plans, activities, paramCommands, imports, null);
    }

    /**
     * B6：带提取任务通道的完整构造（GUI 用 —— 共享真实计划服务的请求工厂与 FX 派发器的
     * 协调器）。无提取通道的构造（{@code extractions = null}）下
     * {@code startExtraction/cancelExtraction} 抛 {@link UnsupportedOperationException}
     * （端口诚实化：不静默吞命令）。
     */
    public InProcessUiport(WorkspaceModel model, Confirmer confirmer, ExtractionPlanService plans,
                          WorkspaceActivityService activities, WorkspaceParamCommandService paramCommands,
                          WorkspaceImportCoordinator imports, WorkspaceExtractionCoordinator extractions) {
        this(model, confirmer, plans, activities, paramCommands, imports, extractions,
                new WorkspaceParamService(PreviewSession.create().lifecycle()));
    }

    public InProcessUiport(WorkspaceModel model, Confirmer confirmer, ExtractionPlanService plans,
                          WorkspaceActivityService activities, WorkspaceParamCommandService paramCommands,
                          WorkspaceImportCoordinator imports, WorkspaceExtractionCoordinator extractions,
                          WorkspaceParamService structureCaches) {
        this.model = Objects.requireNonNull(model, "model");
        this.confirmer = Objects.requireNonNull(confirmer, "confirmer");
        this.plans = Objects.requireNonNull(plans, "plans");
        this.activities = Objects.requireNonNull(activities, "activities");
        this.paramCommands = Objects.requireNonNull(paramCommands, "paramCommands");
        this.imports = Objects.requireNonNull(imports, "imports");
        this.extractions = extractions;     // 可空：未装配提取通道的构造按诚实化口径拒绝命令
        this.structureCaches = Objects.requireNonNull(structureCaches);
    }

    /**
     * 默认参数命令服务（无头调用方）：自持两套全局参数缓存、直连模型的撤销压栈与
     * {@code WorkspaceParamService} 缓存失效（独立预览会话根，与 activities 的默认服务同一形态）。
     */
    static WorkspaceParamCommandService defaultParamCommands(WorkspaceModel model) {
        WorkspaceParamService cacheService = new WorkspaceParamService(PreviewSession.create().lifecycle());
        ParamClipboard clipboard = new ParamClipboard(model::push,
                target -> ParamScope.GLOBAL, (target, imageMode, params) -> { });
        return new WorkspaceParamCommandService(model, cacheService, new GlobalParameterCache(),
                clipboard::pushParamUndo);
    }

    @Override
    public WorkspaceCommands commands() {
        return new WorkspaceCommands() {
            public void cancelWorkspaceActivity() { activities.cancelWorkspaceActivity(); }
            public void cancelPreviewLoad() { activities.cancelPreviewLoad(); }
            public void startPreparse() { activities.startPreparse(); }
            public void startPreparseFor(List<String> paths) { activities.startPreparseFor(paths); }
            public void refreshPreparseProgress() { activities.refreshPreparseProgress(); }
            public void loadPreview(String path, boolean confirmed) { activities.loadPreview(path, confirmed); }
            public void resolvePreviewRegion(long generation, String path, boolean accepted) {
                activities.resolvePreviewRegion(generation, path, accepted);
            }
            public void awaitPreviewInFlight(long millis) { activities.awaitPreviewInFlight(millis); }
            @Override
            public void undo() {
                model.undo();
            }

            @Override
            public void clearItems() {
                if (!model.topLevel().isEmpty()) model.clearItems();
            }

            // ---- B3：勾选命令 + 分组命令集（处置项 6 / 5）----

            @Override
            public void setChecked(List<String> paths, boolean checked) {
                var targets = resolveItems(paths);
                boolean changed = targets.stream().anyMatch(i -> i.selected != checked);
                model.setChecked(targets, checked);
                if (changed) changed("CHECKED_CHANGED");
            }

            @Override
            public void group(List<String> paths, String namePrefix) {
                model.group(resolveItems(paths), namePrefix);
            }

            @Override
            public void ungroup(long groupNo) {
                model.ungroup(groupNo);
            }

            @Override
            public void renameGroup(long groupNo, String newName) {
                var before = groupByNo(groupNo);
                String name = before == null ? null : before.getName();
                boolean defaultNamed = before != null && before.isDefaultNamed();
                model.renameGroup(groupNo, newName);
                if (before != null && (!Objects.equals(name, before.getName()) || defaultNamed != before.isDefaultNamed())) {
                    changed("GROUP_RENAMED");
                }
            }

            @Override
            public void toggleGroupExpanded(long groupNo) {
                if (model.toggleGroupExpanded(groupNo)) changed("GROUP_EXPANDED_CHANGED");
            }

            public void removeItems(List<String> paths) {
                completeStructure(() -> {
                    var targets = resolveItems(paths).stream().filter(i -> !i.removed).distinct().toList();
                    model.removeItems(targets);
                    structureCaches.itemsRemoved(targets);
                    targets.forEach(PreviewItem::resetPreviewState);
                });
            }

            public void removeGroup(long groupNo) {
                completeStructure(() -> {
                    var group = groupByNo(groupNo);
                    if (group == null) return;
                    var members = List.copyOf(group.getMembers());
                    model.removeGroup(group);
                    structureCaches.itemsRemoved(members);
                    members.forEach(PreviewItem::resetPreviewState);
                });
            }

            public com.mhtextractor.uiport.DropVm applyDrop(TargetId dragged, TargetId target, String zone) {
                var source = resolveTarget(dragged);
                var destination = target == null ? null : resolveTarget(target);
                var region = DropResolver.Zone.valueOf(zone);
                if (target == null && region != DropResolver.Zone.BOTTOM) throw new IllegalArgumentException("End requires BOTTOM");
                if (region == DropResolver.Zone.INTO && destination instanceof PreviewItem) throw new IllegalArgumentException("INTO requires group");
                var operation = target == null
                        ? source instanceof GroupItem<?> g ? new DropResolver.MoveGroup(g, model.topLevel().size())
                        : new DropResolver.InsertTop(source, model.topLevel().size())
                        : DropResolver.resolve(model.topLevel(), source, destination, region);
                var result = new com.mhtextractor.uiport.DropVm[1];
                completeStructure(() -> {
                    var drop = model.applyResolvedDrop(operation);
                    if (drop.changed()) {
                        var reparse = new ArrayList<String>();
                        for (var item : drop.affected()) {
                            if (!item.removed && drop.affectedBefore().get(item) != item.parentGroup) {
                                if (item.parentGroup != null) {
                                    item.textItemParams = null;
                                    item.imageItemParams = null;
                                }
                                structureCaches.paramsChanged(true, item);
                                item.resetPreviewState();
                                if (plans.effectiveParams(item) != null) reparse.add(item.path);
                            }
                        }
                        if (!reparse.isEmpty()) activities.startPreparseFor(reparse);
                    }
                    result[0] = new com.mhtextractor.uiport.DropVm(drop.changed(),
                            drop.changed() ? drop.affected().stream().map(i -> i.path).toList() : List.of());
                });
                return result[0];
            }

            // ---- B4：参数命令族（处置项 3 / 4）----

            @Override
            public void setGlobalParams(boolean imageMode, AppConfig params) {
                paramCommands.setGlobalParams(imageMode, params);
            }

            @Override
            public void setGroupParams(long groupNo, boolean imageMode, AppConfig params) {
                paramCommands.setGroupParams(groupNo, imageMode, params);
            }

            @Override
            public void setItemParams(String path, boolean imageMode, AppConfig params) {
                paramCommands.setItemParams(path, imageMode, params);
            }

            @Override
            public void clearParams(List<TargetId> fallbackTargets, boolean imageMode) {
                paramCommands.clearParams(fallbackTargets, imageMode);
            }

            @Override
            public void applyGlobalParams(TargetId target, boolean imageMode) {
                paramCommands.applyGlobalParams(target, imageMode);
            }

            // ---- B5-1：导入编排 ----

            @Override
            public void importPaths(List<String> addresses, String sourceDesc, boolean fromDrag) {
                imports.importPaths(addresses, sourceDesc, fromDrag);
            }

            @Override
            public void applyImportPlan(ImportPlanVm plan) {
                imports.applyPlan(plan);
            }

            // ---- B6：提取任务通道 ----

            @Override
            public void startExtraction(boolean checkedOnly) {
                var channel = extractionChannel();
                channel.startExtraction(checkedOnly);
                // Commands and coordinator callbacks share the host serial thread. Project its
                // state after a successful start, before queued worker callbacks can be delivered.
                var event = new PortEvent.RunningChanged(channel.running.get(), channel.generation());
                for (var listener : List.copyOf(listeners)) deliver(listener, event);
            }

            @Override
            public void cancelExtraction() {
                var channel = extractionChannel();
                if (channel.running.get()) channel.cancelExtraction();
            }
        };
    }

    /** B6：提取通道按诚实化口径解析（未装配 = 抛异常，不静默吞命令）。 */
    private WorkspaceExtractionCoordinator extractionChannel() {
        if (extractions == null) {
            throw new UnsupportedOperationException("Extraction channel is not wired");
        }
        return extractions;
    }

    @Override
    public WorkspaceQueries queries() {
        return new WorkspaceQueries() {
            public long activityGeneration() { return activities.generation(); }
            public long previewGeneration() { return activities.previewGeneration(); }
            public String previewLoadingPath() { return activities.loadingPath(); }
            public WorkspaceVm workspace() { return snapshot(); }
            public AppConfig runtimeConfig() { return plans.runtimeConfig(); }
            public List<OutputUnitVm> outputUnitPlan(boolean checkedOnly) { return plans.outputUnitPlan(checkedOnly); }
            public ParamSchemaVm paramSchema(boolean imageMode) { return ParamSchemaService.schema(imageMode); }
        };

package com.mhtextractor.app;

import com.mhtextractor.i18n.I18n;
import com.mhtextractor.model.AppConfig;
import com.mhtextractor.model.GroupItem;
import com.mhtextractor.model.PreviewItem;
import com.mhtextractor.uiport.PortEvent;
import com.mhtextractor.uiport.PortEvent.ParamChangeKind;
import com.mhtextractor.uiport.TargetId;
import lombok.extern.slf4j.Slf4j;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;

/**
 * 工作区参数命令服务（B4，处置项 3 / 4）—— 参数应用 / 清除 / 应用到全局的<b>唯一实现点</b>。
 *
 * <p><b>解决什么问题</b>：参数域的五条写路径原先由 {@code gui.controller.ParamDomainController} 的
 * {@code applyConfirmedParams / applyGroupParams / applyItemParams / applyGlobalParamsTo /
 * clearParamsForTargets} 实现（GUI 直写条目 / 组 / 全局参数 + 撤销压栈 + 缓存失效）。本类把
 * 「写入 + 撤销压栈 + 磁盘缓存失效（规则 a）」这三段语义<b>逐字</b>搬入 app 层，端口命令
 * （{@code uiport.WorkspaceCommands} 的 B4 成员）与本类同源转发；前端（GUI）不再持有参数写入逻辑，
 * 只按 {@link PortEvent.ParamStateChanged} 事件执行列表刷新与参数色刷新。</p>
 *
 * <p><b>语义逐字保留</b>：全局 / 组 / 条目三层覆盖、{@code imageMode} 分文本 / 图片参数、撤销载荷
 * （PARAM_SET 经 {@link ParamClipboard#pushParamUndo}（批量应用累积为整批一条），CLEAR_PARAMS 经
 * {@link UndoRecords#clearParams}，APPLY_GLOBAL 经 {@link UndoRecords#applyGlobal}）、缓存失效
 * （经 {@link WorkspaceParamService} 收口，GUI 不得直调缓存删除规则）、勾选优先口径
 * （{@link ParamTargets#resolve}）、以及 {@code log.maincontroller.28} 的日志键与实参 —— 全部与搬移前一致。</p>
 *
 * <p><b>事件契约</b>：每条<b>成功</b>命令（确实改变了参数状态）在完成后同步发布一次
 * {@link PortEvent.ParamStateChanged}；no-op（组不存在 / 路径不存在 / 无有效目标 / 生效参数为空）
 * 不发布、不压撤销记录。订阅见 {@link #subscribe}（与 {@code WorkspaceActivityService} 同一形态）。</p>
 *
 * <p><b>零 JavaFX</b>：仅依赖 model / i18n（日志键）与 uiport 的事件类型，由
 * {@code ArchitectureTest} 的零 JavaFX 不变式覆盖。</p>
 */
@Slf4j
public final class WorkspaceParamCommandService {

    /** 宿主上下文：模型 / 撤销 / 缓存失效 / 两套全局参数缓存的具名出口（GUI 匿名类逐个转发）。 */
    public interface Context {
        /** 全部条目（含组内成员、含已移除），不可变快照。 */
        List<PreviewItem> allItems();

        /** 顶层数据序（含组条目），不可变快照。 */
        List<Object> dataOrder();

        /** 撤销压栈（模型唯一入口 {@code WorkspaceModel.push}）。 */
        void pushUndo(UndoManager.Record<PreviewItem> record);

        /**
         * PARAM_SET 撤销压栈唯一出口（{@code ParamClipboard.pushParamUndo}）：
         * 批量应用期间只累积快照、整批一条。
         */
        void pushParamUndo(boolean imageMode, String path, Integer groupNo, AppConfig before);

        /** 缓存失效收口（规则 a；{@code imageMode == false} 时为 no-op，守卫在服务内）。 */
        WorkspaceParamService cacheService();

        /** 两套全局「已确认参数」缓存（写入 = 整体替换引用；null = 该模式尚未确认）。 */
        GlobalParameterCache globalParams();
    }

    /** PARAM_SET 撤销压栈出口的函数形态（与 {@link ParamClipboard#pushParamUndo} 同签名）。 */
    @FunctionalInterface
    public interface ParamUndoPusher {
        void push(boolean imageMode, String path, Integer groupNo, AppConfig before);
    }

    private final Context context;
    private final List<Consumer<PortEvent>> listeners = new CopyOnWriteArrayList<>();

    public WorkspaceParamCommandService(Context context) {
        this.context = java.util.Objects.requireNonNull(context, "context");
    }

    /**
     * 模型直连便捷构造（B4）：撤销压栈 = {@code model.push}、数据序 / 全条目 = {@code model} 快照。
     * 供 GUI 与无头调用方少写一个 Context（六个出口都是模型 / 服务直连的常见形态）。
     */
    public WorkspaceParamCommandService(WorkspaceModel model, WorkspaceParamService cacheService,
                                        GlobalParameterCache globalParams, ParamUndoPusher pushParamUndo) {
        this(new Context() {
            public List<PreviewItem> allItems() { return model.allItems(); }
            public List<Object> dataOrder() { return model.topLevel(); }
            public void pushUndo(UndoManager.Record<PreviewItem> record) { model.push(record); }
            public void pushParamUndo(boolean imageMode, String path, Integer groupNo, AppConfig before) {
                pushParamUndo.push(imageMode, path, groupNo, before);
            }
            public WorkspaceParamService cacheService() { return cacheService; }
            public GlobalParameterCache globalParams() { return globalParams; }
        });
    }

    /** 订阅参数状态变更（句柄 {@code close()} 即退订，幂等）。 */
    public AutoCloseable subscribe(Consumer<PortEvent> listener) {
        listeners.add(listener);
        return () -> listeners.remove(listener);
    }

    private void emit(PortEvent event) {
        for (Consumer<PortEvent> listener : listeners) {
            listener.accept(event);
        }
    }

    // ==================== B4-1：参数应用三命令（原 applyConfirmedParams / applyGroupParams / applyItemParams） ====================

    /**
     * 全局参数确认写入：写入当前模式已确认参数缓存并刷新工作区；入撤销栈（PARAM_SET）。
     * 原 {@code ParamDomainController.applyConfirmedParams} 的参数应用语义逐字搬入（UI 派生刷新由前端按事件做）。
     */
    public void setGlobalParams(boolean imageMode, AppConfig params) {
        GlobalParameterCache global = context.globalParams();
        AppConfig before = imageMode ? global.image() : global.text();
        if (imageMode) {
            global.set(true, params);
        } else {
            global.set(false, params);
        }
        context.pushParamUndo(imageMode, null, null, before);
        List<PreviewItem> all = context.allItems();
        // 规则 (a)：全局参数变化 → 全部条目缓存目录删除（保守全删：有独立参数的条目删除也只是下次预览重建，语义安全）
        context.cacheService().paramsChanged(imageMode, all);
        emit(new PortEvent.ParamStateChanged(ParamChangeKind.SET_GLOBAL, imageMode, pathsOf(all)));
    }

    /**
     * 组参数写入（组号寻址；组不存在时为 no-op）：入撤销栈（PARAM_SET，组参数设置可撤销）。
     * 原 {@code ParamDomainController.applyGroupParams} 的参数应用语义逐字搬入。
     */
    public void setGroupParams(long groupNo, boolean imageMode, AppConfig params) {
        GroupItem<PreviewItem> group = groupByNo(groupNo);
        if (group == null) {
            return;   // 组不存在 → 纯 no-op
        }
        AppConfig before = imageMode ? group.getImageParamsCache() : group.getTextParamsCache();
        if (imageMode) {
            group.setImageParamsCache(params);
        } else {
            group.setTextParamsCache(params);
        }
        context.pushParamUndo(imageMode, null, group.getGroupNo(), before);
        List<PreviewItem> members = group.getMembers().stream().filter(m -> !m.removed).toList();
        // 规则 (a)：组参数变化 → 该组成员缓存目录删除
        context.cacheService().paramsChanged(imageMode, members);
        emit(new PortEvent.ParamStateChanged(ParamChangeKind.SET_GROUP, imageMode, pathsOf(members)));
    }

    /**
     * 条目级参数写入（路径寻址；路径不存在时静默跳过）：不写全局，仅清缓存重解析该条目；
     * 入撤销栈（PARAM_SET）。原 {@code ParamDomainController.applyItemParams} 的参数应用语义逐字搬入。
     */
    public void setItemParams(String path, boolean imageMode, AppConfig params) {
        PreviewItem item = findByPath(path);
        if (item == null) {
            return;   // 路径不存在 → 静默跳过
        }
        AppConfig before = imageMode ? item.imageItemParams : item.textItemParams;
        if (imageMode) {
            item.imageItemParams = params;
        } else {
            item.textItemParams = params;
        }
        context.pushParamUndo(imageMode, item.path, null, before);
        // 规则 (a)：参数变化 → 删该项目缓存目录（单条目重载 —— 与批量重载语义不同，勿合并）
        context.cacheService().paramsChanged(imageMode, item);
        emit(new PortEvent.ParamStateChanged(ParamChangeKind.SET_ITEM, imageMode, List.of(item.path)));
    }

    // ==================== B4-2：清除参数 / 应用到全局（原 clearParamsForTargets / applyGlobalParamsTo） ====================

    /**
     * 清除参数：只清当前模式。勾选优先（{@link ParamTargets#resolve}，勾选集合优先 → 回退
     * {@code fallbackTargets}）；组外条目 → 清条目级参数；组内成员/组条目 → 清整组组参数（按组去重）；
     * 无参数目标自然跳过；一次操作一条 CLEAR_PARAMS 撤销记录（before 快照），一次撤销全部恢复。
     * 原 {@code ParamDomainController.clearParamsForTargets} 逐字搬入（{@code log.maincontroller.28} 一并）。
     */
    public void clearParams(List<TargetId> fallbackTargets, boolean imageMode) {
        List<PreviewItem> visible = context.allItems().stream().filter(i -> !i.removed).toList();
        List<Object> rawTargets = ParamTargets.resolve(visible, resolveFallback(fallbackTargets));
        clearParamsForTargets(rawTargets, imageMode);
    }

    /**
     * 应用到全局：目标生效参数集写入当前模式全局缓存，清空当前模式所有独立参数（条目级 + 组，
     * 含目标自身），全部条目继承新全局；另一模式独立参数不受影响。入撤销栈（APPLY_GLOBAL，
     * 含应用前完整参数快照）。原 {@code ParamDomainController.applyGlobalParamsTo} 逐字搬入
     * （生效参数解析经 {@link EffectiveParamsService}，与 GUI 的 {@code effectiveForObject} 同源）。
     */
    public void applyGlobalParams(TargetId target, boolean imageMode) {
        Object resolved = resolveTarget(target);
        if (resolved == null) {
            return;   // 目标不可解析 → 纯 no-op
        }
        GlobalParameterCache global = context.globalParams();
        AppConfig params = EFFECTIVE.effectiveFor(resolved,
                new EffectiveParamsService.Context(imageMode, global.text(), global.image()));
        if (params == null) {
            return;   // 目标无生效参数（与 GUI 的入口守卫同义）→ 纯 no-op
        }
        // 撤销快照（拍板 2026-09-22）：应用前的全局参数 + 全部独立参数，撤销可完整回退
        AppConfig globalBefore = imageMode ? global.image() : global.text();
        Map<String, AppConfig> itemBefore = new HashMap<>();
        for (PreviewItem it : context.allItems()) {
            itemBefore.put(it.path, imageMode ? it.imageItemParams : it.textItemParams);
        }
        Map<Integer, AppConfig> groupBefore = new HashMap<>();
        for (Object o : context.dataOrder()) {
            if (o instanceof GroupItem<?> g) {
                groupBefore.put(g.getGroupNo(),
                        imageMode ? g.getImageParamsCache() : g.getTextParamsCache());
            }
        }
        if (imageMode) {
            global.set(true, params);
        } else {
            global.set(false, params);
        }
        for (PreviewItem it : context.allItems()) {
            if (imageMode) {
                it.imageItemParams = null;
            } else {
                it.textItemParams = null;
            }
        }
        for (Object o : context.dataOrder()) {
            if (o instanceof GroupItem<?> g) {
                if (imageMode) {
                    g.setImageParamsCache(null);
                } else {
                    g.setTextParamsCache(null);
                }
            }
        }
        context.pushUndo(UndoRecords.applyGlobal(imageMode, globalBefore, itemBefore, groupBefore));
        List<PreviewItem> all = context.allItems();
        // 规则 (a)：全局参数写入 + 全部独立参数清空 → 全部条目生效参数变化 → 删除全部缓存目录
        context.cacheService().paramsChanged(imageMode, all);
        emit(new PortEvent.ParamStateChanged(ParamChangeKind.APPLY_GLOBAL, imageMode, pathsOf(all)));
    }

    /** 清除参数本体（原 {@code ParamDomainController.clearParamsForTargets} 逐字搬入，含日志键与实参顺序）。 */
    private void clearParamsForTargets(List<Object> rawTargets, boolean imageMode) {
        List<PreviewItem> topItems = new ArrayList<>();
        Set<GroupItem<PreviewItem>> groups = new LinkedHashSet<>();
        for (Object o : rawTargets) {
            if (o instanceof PreviewItem it && !it.removed) {
                if (it.parentGroup != null) {
                    if ((imageMode ? it.parentGroup.getImageParamsCache()
                                   : it.parentGroup.getTextParamsCache()) != null) {
                        groups.add(it.parentGroup);
                    }
                } else if ((imageMode ? it.imageItemParams : it.textItemParams) != null) {
                    topItems.add(it);
                }
            } else if (o instanceof GroupItem<?> g) {
                GroupItem<PreviewItem> grp = WorkspaceStructure.asPreviewGroup(g);
                if ((imageMode ? grp.getImageParamsCache() : grp.getTextParamsCache()) != null) {
                    groups.add(grp);
                }
            }
        }
        if (topItems.isEmpty() && groups.isEmpty()) {
            return;
        }
        // 撤销快照：清除前该模式参数（只收录本次实际清除的目标）
        Map<String, AppConfig> itemBefore = new HashMap<>();
        for (PreviewItem it : topItems) {
            itemBefore.put(it.path, imageMode ? it.imageItemParams : it.textItemParams);
        }
        Map<Integer, AppConfig> groupBefore = new HashMap<>();
        for (GroupItem<PreviewItem> grp : groups) {
            groupBefore.put(grp.getGroupNo(),
                    imageMode ? grp.getImageParamsCache() : grp.getTextParamsCache());
        }
        if (imageMode) {
            for (PreviewItem it : topItems) {
                it.imageItemParams = null;
            }
            for (GroupItem<PreviewItem> grp : groups) {
                grp.setImageParamsCache(null);
            }
        } else {
            for (PreviewItem it : topItems) {
                it.textItemParams = null;
            }
            for (GroupItem<PreviewItem> grp : groups) {
                grp.setTextParamsCache(null);
            }
        }
        context.pushUndo(UndoRecords.clearParams(imageMode, itemBefore, groupBefore));
        // 受影响条目：清除条目参数的项目 + 清除组参数的各组全部有效成员
        List<PreviewItem> affected = new ArrayList<>(topItems);
        for (GroupItem<PreviewItem> grp : groups) {
            affected.addAll(grp.getMembers().stream().filter(m -> !m.removed).toList());
        }
        // 规则 (a)：清除参数也是参数变化（生效参数回落组/全局）→ 受影响条目缓存目录删除
        context.cacheService().paramsChanged(imageMode, affected);
        log.info(I18n.msg("log.maincontroller.28", topItems.size(), groups.size(), modeWord(imageMode)));
        emit(new PortEvent.ParamStateChanged(ParamChangeKind.CLEAR, imageMode, pathsOf(affected)));
    }

    // ==================== 内部工具 ====================

    /** 生效参数解析（与 GUI {@code effectiveForObject} 同源的唯一实现 {@link EffectiveParamsService}，无状态可共享）。 */
    private static final EffectiveParamsService EFFECTIVE = new EffectiveParamsService();

    private PreviewItem findByPath(String path) {
        if (path == null) {
            return null;
        }
        for (PreviewItem it : context.allItems()) {
            if (path.equals(it.path)) {
                return it;
            }
        }
        return null;
    }

    private GroupItem<PreviewItem> groupByNo(long groupNo) {
        for (Object o : context.dataOrder()) {
            if (o instanceof GroupItem<?> raw) {
                GroupItem<PreviewItem> g = WorkspaceStructure.asPreviewGroup(raw);
                if (g.getGroupNo() == groupNo) {
                    return g;
                }
            }
        }
        return null;
    }

    /** {@link TargetId} → 工作区对象（条目按路径、组按组号）；不可解析返回 {@code null}。 */
    private Object resolveTarget(TargetId id) {
        if (id == null) {
            return null;
        }
        if (id.path() != null) {
            return findByPath(id.path());
        }
        return groupByNo(id.groupNo());
    }

    /** 回退目标列表 → 第一个可解析的单个目标（GUI 的回退恒为单个右键命中 / 当前选中，可为 null）。 */
    private Object resolveFallback(List<TargetId> targets) {
        if (targets == null) {
            return null;
        }
        for (TargetId id : targets) {
            Object o = resolveTarget(id);
            if (o != null) {
                return o;
            }
        }
        return null;
    }

    private static List<String> pathsOf(List<PreviewItem> items) {
        List<String> out = new ArrayList<>();
        for (PreviewItem it : items) {
            if (it != null && it.path != null) {
                out.add(it.path);
            }
        }
        return List.copyOf(out);
    }

    /** 日志文案里的模式词（图片/文本 → Image/Text），供 log.* 模板的 {0} 占位符使用 */
    private static String modeWord(boolean imageMode) {
        return I18n.get(imageMode ? "mode.image" : "mode.text");
    }
}
package com.mhtextractor.app;

import com.mhtextractor.i18n.ErrorCode;
import com.mhtextractor.model.GroupItem;
import com.mhtextractor.model.PreviewItem;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

/**
 * 提取前置校验（会话 18 · E4-2）—— 从 {@code MainController.onStartProcessing} 抽出的**纯决策逻辑**。
 *
 * <p><b>为什么抽它</b>：这段校验原先内联在 GUI 事件处理器里（输入/输出目录、目录是否存在、
 * 列表是否为空），并与 {@code showAlert} 交织 —— 于是"到底什么条件下允许开始提取"这件事
 * <b>只能靠读 GUI 代码才能知道，也无法单测</b>。抽成纯函数后：
 * 调用方拿到 {@link ErrorCode}（结构化结果）自行决定怎么展示（弹窗/日志/退出码），
 * 业务规则与展示彻底分离。</p>
 *
 * <p><b>零 JavaFX</b>：本类只做字符串/目录/计数判断，属目标 ② 的 {@code app} 层
 * （由 {@code ArchitectureTest} 强制依赖闭包零 {@code javafx}）。</p>
 *
 * <p><b>行为等价性</b>：判定顺序与判定条件与原代码<b>逐条一致</b>：
 * 输入目录为空 → 输出目录为空 → 输入目录不存在 → 无可提取条目（区分"从未找到"与"全被移除"）。</p>
 */
public final class ExtractionPreconditions {

    /** 校验所需的事实（由调用方从自己的 UI/状态中取出，本类不读任何全局状态） */
    public record Facts(
            String inputFolder,
            String outputFolder,
            boolean inputFolderIsDirectory,
            /* 列表中的条目总数（含被移除的） */
            int totalItems,
            /* 当前可见（未被移除）的条目数 */
            int visibleItems) {
    }

    private ExtractionPreconditions() {
    }

    /**
     * 校验是否允许开始提取。
     *
     * @return {@code null} 表示<b>允许</b>；非 null 表示被拒绝及原因（调用方据此展示）
     */
    public static ErrorCode validate(Facts facts) {
        if (facts == null) {
            return ErrorCode.INPUT_DIR_INVALID;
        }
        if (isBlank(facts.inputFolder())) {
            return ErrorCode.INPUT_DIR_INVALID;
        }
        if (isBlank(facts.outputFolder())) {
            return ErrorCode.OUTPUT_DIR_INVALID;
        }
        if (!facts.inputFolderIsDirectory()) {
            return ErrorCode.INPUT_DIR_MISSING;
        }
        if (facts.visibleItems() == 0) {
            // 区分"从未导入到任何文件"与"导入了但全被移除"——原代码即如此区分
            return facts.totalItems() == 0 ? ErrorCode.NO_MHT_FOUND : ErrorCode.KEEP_AT_LEAST_ONE;
        }
        return null;
    }

    /** 便捷方法：直接从目录字符串判断（内部做一次 {@code File.isDirectory()}），便于无头调用 */
    public static ErrorCode validate(String inputFolder, String outputFolder,
                                     int totalItems, int visibleItems) {
        boolean isDir = !isBlank(inputFolder) && new File(inputFolder).isDirectory();
        return validate(new Facts(inputFolder, outputFolder, isDir, totalItems, visibleItems));
    }

    // ==================== 单条件形态（供 UI 逐条委托，保留顺序与告警级别） ====================

    /**
     * 单条件形态存在的理由：GUI 的原始写法是<b>逐条 if + 各自不同的告警级别</b>
     * （输入/输出/条目数为 WARNING，目录不存在为 ERROR），且判定<b>顺序</b>本身是语义的一部分。
     * 若 UI 直接调用聚合 {@link #validate(Facts)}，就会把顺序与级别压平 —— 那是行为变更。
     *
     * <p>因此同时提供"聚合形态"（无头调用方一次问清楚）与"单条件形态"（UI 逐条问、逐条弹）。
     * 两者共享同一批判断，不会出现两套规则漂移。</p>
     *
     * @return {@code null} = 该条件通过
     */
    public static ErrorCode blankInput(String inputFolder) {
        return isBlank(inputFolder) ? ErrorCode.INPUT_DIR_INVALID : null;
    }

    /** 见 {@link #blankInput(String)} 的说明 */
    public static ErrorCode blankOutput(String outputFolder) {
        return isBlank(outputFolder) ? ErrorCode.OUTPUT_DIR_INVALID : null;
    }

    /** 见 {@link #blankInput(String)} 的说明（调用方应先确认目录字符串非空） */
    public static ErrorCode inputNotDirectory(String inputFolder) {
        if (isBlank(inputFolder)) {
            return ErrorCode.INPUT_DIR_INVALID;
        }
        return new File(inputFolder).isDirectory() ? null : ErrorCode.INPUT_DIR_MISSING;
    }

    /** 见 {@link #blankInput(String)} 的说明 */
    public static ErrorCode noExtractableItems(int totalItems, int visibleItems) {
        if (visibleItems != 0) {
            return null;
        }
        return totalItems == 0 ? ErrorCode.NO_MHT_FOUND : ErrorCode.KEEP_AT_LEAST_ONE;
    }

    /**
     * 功能一：开启"只提取选中的列表项"但没有勾选任何可见项时的拒绝码。
     *
     * <p>与 {@link #noExtractableItems(int, int)} 分开：后者是三态语义（从未导入 / 全被移除），
     * 不能把"可见项 &gt; 0 但勾选为 0"塞进去，否则会破坏其既有三态。调用方只在开关打开时调用本方法。
     *
     * @param participating 本次会参与提取的可见项数（开关打开时 = 勾选且未移除的数量）
     * @return {@code null} = 通过；否则 {@link ErrorCode#NO_CHECKED_ITEMS}
     */
    public static ErrorCode noCheckedItems(int participating) {
        return participating == 0 ? ErrorCode.NO_CHECKED_ITEMS : null;
    }

    // ==================== 未命名组规则（步骤 3 · 功能一） ====================

    /**
     * 未命名组判定：{@link GroupItem#isDefaultNamed()} 为 true（「从未被用户重命名过」）的组。
     *
     * <p>语义来源（需求 §1.1 决策 1.1–1.12）：手工建组即默认名；用户一旦<b>提交</b>过改名，
     * 标记永久为 false（改回默认名也不再提醒）；导入自动建组恒为 false。撤销/重做恢复的组
     * 保留其当时的标记（记录与快照持组<b>实例</b>引用，标记随对象走）。</p>
     *
     * <p>本规则只产<b>组名列表</b>，文案与展示全部留在 GUI 层（本类零 I18n 引用是架构硬约束）。</p>
     *
     * @param groups 顶层组列表（调用方从数据序投影中取出）
     * @return 未命名组名列表（空 = 通过，无需提醒）
     */
    public static List<String> unnamedGroups(List<GroupItem<PreviewItem>> groups) {
        List<String> names = new ArrayList<>();
        if (groups != null) {
            for (GroupItem<PreviewItem> g : groups) {
                if (g.isDefaultNamed()) {
                    names.add(g.getName());
                }
            }
        }
        return List.copyOf(names);
    }

    /**
     * 功能一：过滤出"过滤后仍会产生单元"的顶层组（开关打开时 ≥1 个勾选且未移除的成员；
     * 开关关闭时原样返回）。未命名组提醒只针对这些组。纯函数。
     */
    public static List<GroupItem<PreviewItem>> participatingGroups(
            List<GroupItem<PreviewItem>> groups, boolean checkedOnly) {
        if (groups == null || !checkedOnly) {
            return groups == null ? List.of() : List.copyOf(groups);
        }
        List<GroupItem<PreviewItem>> out = new ArrayList<>();
        for (GroupItem<PreviewItem> g : groups) {
            for (Object m : g.getMembers()) {
                if (m instanceof PreviewItem it && !it.removed && it.selected) {
                    out.add(g);
                    break;
                }
            }
        }
        return List.copyOf(out);
    }

    // ==================== 展示级别（把"该用 WARNING 还是 ERROR"也变成规则的一部分） ====================

    /**
     * 告警级别。业务规则不仅决定"是否拒绝"，也决定"该多严重地提示" ——
     * 把它放在这里，UI 侧就只需一句 {@code showAlert(level, code.message())}，
     * 不必再散落 {@code if (code == INPUT_DIR_MISSING) ERROR else WARNING} 这类判断。
     *
     * <p>对应原 {@code MainController.onStartProcessing} 的实测行为：
     * 输入/输出目录为空、条目数为 0 → WARNING；输入目录不存在 → ERROR。</p>
     */
    public enum Level { WARNING, ERROR }

    /**
     * 按错误码给出展示级别（未知码保守取 WARNING）。
     * 功能一：{@link ErrorCode#NO_CHECKED_ITEMS} 必须 ERROR（居中卡片、须确认）。
     */
    public static Level levelOf(ErrorCode code) {
        return code == ErrorCode.INPUT_DIR_MISSING || code == ErrorCode.NO_CHECKED_ITEMS
                ? Level.ERROR : Level.WARNING;
    }

    /**
     * 断言形态：条件不满足时返回带级别的拒绝结果，满足时返回 {@code null}。
     *
     * <p>存在的意义是<b>压缩 UI 侧的样板</b>：让控制器写成
     * {@code var d = deny(blankInput(in)); if (d != null) { ... }} 一行一条，
     * 而不是 {@code (x = f()) != null} 那种容易写错、且行数翻倍的形态。</p>
     */
    public record Denial(ErrorCode code, Level level) {
    }

    public static Denial deny(ErrorCode code) {
        return code == null ? null : new Denial(code, levelOf(code));
    }

    private static boolean isBlank(String s) {
        return s == null || s.trim().isEmpty();
    }
}
package com.mhtextractor.app;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.model.PreviewItem;
import com.mhtextractor.processor.PerFileOverrides;
import com.mhtextractor.util.OutputUnitPlanner;
import com.mhtextractor.uiport.OutputUnitVm;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * 提取运行时配置与输出单元计划（P3-3b-3，矩阵缺口 7/8）：把
 * {@code gui.ExtractionTaskCoordinator.buildRuntimeConfig} 与 {@code startExtractionTask} 里的
 * 两段<b>纯计算</b>原样搬到 app 层（只搬不改：配置字段写入顺序、单元参数补充顺序与搬迁前逐字一致）。
 *
 * <p>零 JavaFX、零 I18n；不产任何文案（{@code log.maincontroller.33} 的日志键与实参构造留在 gui 侧）。</p>
 */
public final class ExtractionPlanService {

    /** 当前已确认参数和会话状态；由宿主提供实时读取，不缓存控件值。 */
    public interface Context {
        List<Object> dataOrder();
        boolean imageMode();
        AppConfig textParamsCache();
        AppConfig imageParamsCache();
        String inputFolder();
        String outputFolder();
        boolean openFolderAfterComplete();
    }

    private final Context context;
    private String sessionOutputFolder;

    public ExtractionPlanService(Context context) {
        this.context = java.util.Objects.requireNonNull(context);
    }

    /** 正式运行前绑定已建立的会话目录；查询本身不创建目录。 */
    public void setSessionOutputFolder(String folder) {
        sessionOutputFolder = folder;
    }

    public AppConfig runtimeConfig() {
        return runtimeConfig(context.imageMode(), context.imageParamsCache(), context.textParamsCache(),
                context.inputFolder(), context.outputFolder(), context.openFolderAfterComplete());
    }

    AppConfig effectiveParams(PreviewItem item) {
        return com.mhtextractor.model.ParamScope.effectiveParams(item.parentGroup,
                item.textItemParams, item.imageItemParams, context.imageMode(),
                context.textParamsCache(), context.imageParamsCache());
    }

    AppConfig effectiveImageParams(PreviewItem item) {
        return com.mhtextractor.model.ParamScope.effectiveImageParams(item.parentGroup,
                item.imageItemParams, context.imageParamsCache());
    }

    public List<OutputUnitVm> outputUnitPlan(boolean checkedOnly) {
        return plan(context.dataOrder(), context.imageMode(), context.textParamsCache(), context.imageParamsCache(),
                sessionOutputFolder == null ? context.outputFolder() : sessionOutputFolder,
                context.inputFolder(), context.outputFolder(), context.openFolderAfterComplete(), checkedOnly)
                .stream().map(u -> new OutputUnitVm(u.getOutputName(), u.isGroup(), u.getParams(),
                        u.getPaths(), u.getOutputPath(), u.getOutputName() == null ? "core.ungrouped" : null)).toList();
    }

    /**
     * 输出单元规划字段视图的 gui 侧返回类型别名（协变返回）：让 gui 层对视图类型的引用
     * 落在 app 层（gui 直连业务包计数只减不增，不再直连 {@code util} 的视图接口）。
     */
    public interface ItemView extends OutputUnitPlanner.ItemView<PreviewItem> {
    }

    /** 原 {@code MainController.ITEM_VIEW}（阶段 8）：路径 / 来源目录 / 移除标记 / 条目级参数；checked 用默认恒 true。 */
    private static final ItemView ITEM_VIEW = new ItemView() {
        @Override
        public String path(PreviewItem item) {
            return item.path;
        }

        @Override
        public String sourceFolder(PreviewItem item) {
            return item.sourceFolder;
        }

        @Override
        public boolean removed(PreviewItem item) {
            return item.removed;
        }

        @Override
        public AppConfig textItemParams(PreviewItem item) {
            return item.textItemParams;
        }

        @Override
        public AppConfig imageItemParams(PreviewItem item) {
            return item.imageItemParams;
        }
    };

    /**
     * 字段视图（原 {@code MainController} 的 Host 实现）：功能一（只提取选中）开关打开时把
     * "参与"判定交给 checked（条目勾选）；关闭时用默认视图（checked 恒 true）。
     */
    public static ItemView itemView(boolean checkedOnly) {
        if (!checkedOnly) {
            return ITEM_VIEW;
        }
        OutputUnitPlanner.ItemView<PreviewItem> decorated = OutputUnitPlanner.withChecked(ITEM_VIEW, it -> it.selected);
        return new ItemView() {
            @Override public String path(PreviewItem item) { return decorated.path(item); }
            @Override public String sourceFolder(PreviewItem item) { return decorated.sourceFolder(item); }
            @Override public boolean removed(PreviewItem item) { return decorated.removed(item); }
            @Override public boolean checked(PreviewItem item) { return decorated.checked(item); }
            @Override public AppConfig textItemParams(PreviewItem item) { return decorated.textItemParams(item); }
            @Override public AppConfig imageItemParams(PreviewItem item) { return decorated.imageItemParams(item); }
        };
    }

    /**
     * 以已确认参数（未确认时用默认参数）+ 主窗口 GUI 状态构建运行时提取配置
     * （原 {@code ExtractionTaskCoordinator.buildRuntimeConfig}，逐条照搬）：
     * 取当前模式参数缓存，null 则新建默认实例，随后按序补四个运行时字段。
     *
     * <p><b>注意</b>：参数缓存非 null 时就地修改该实例（搬迁前语义）。</p>
     */
    public static AppConfig runtimeConfig(boolean imageMode, AppConfig imageParams, AppConfig textParams,
                                          String inputFolder, String outputFolder, boolean openFolderAfterComplete) {
        AppConfig config = imageMode ? imageParams : textParams;
        if (config == null) {
            config = new AppConfig();
        }
        config.setInputFolder(inputFolder);
        config.setOutputFolder(outputFolder);
        config.setImageModeEnabled(imageMode);
        config.setOpenFolderAfterComplete(openFolderAfterComplete);
        return config;
    }

    /**
     * 构建输出单元计划（原 {@code ExtractionTaskCoordinator.startExtractionTask} 内的计划组装，
     * 逐条照搬）：先按数据序 + 字段视图（功能一按需过滤勾选）规划单元，再对每个单元按序补
     * 运行时字段（{@code setInputFolder → setOutputFolder → setImageModeEnabled →
     * setOpenFolderAfterComplete}）。纯计算：不产文案、不触碰控件状态。
     */
    public static List<OutputUnitPlanner.OutputUnit> plan(List<Object> dataOrder, boolean imageMode,
                                                          AppConfig textParams, AppConfig imageParams,
                                                          String sessionOutputFolder, String inputFolder,
                                                          String outputFolder, boolean openFolderAfterComplete,
                                                          boolean checkedOnly) {
        List<OutputUnitPlanner.OutputUnit> units = OutputUnitPlanner.plan(
                dataOrder, itemView(checkedOnly), imageMode, textParams, imageParams, sessionOutputFolder);
        for (OutputUnitPlanner.OutputUnit unit : units) {
            AppConfig params = unit.getParams();
            params.setInputFolder(inputFolder);
            params.setOutputFolder(outputFolder);
            params.setImageModeEnabled(imageMode);
            params.setOpenFolderAfterComplete(openFolderAfterComplete);
        }
        return units;
    }

    /**
     * 构建「每文件覆盖」映射（原 {@code ExtractionTaskCoordinator.overrides}，逐条照搬）：
     * 按传入顺序放入 {@link LinkedHashMap}，键为 {@code item.path}，值为
     * {@code chapterEnabled} / {@code titleOverride} 两字段的覆盖。
     */
    public static Map<String, PerFileOverrides> overrides(List<PreviewItem> items) {
        Map<String, PerFileOverrides> map = new LinkedHashMap<>();
        for (PreviewItem item : items) {
            // 标题覆盖 = 用户在查看器「提取标题」文本框里的编辑值（null/空白 = 用提取值）
            map.put(item.path, new PerFileOverrides(item.chapterEnabled, item.titleOverride));
        }
        return map;
    }
}

package com.mhtextractor.backend;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.mhtextractor.app.*;
import com.mhtextractor.core.SourceParsers;
import com.mhtextractor.model.AppConfig;
import com.mhtextractor.model.ExtractionStats;
import com.mhtextractor.model.ParamScope;
import com.mhtextractor.model.PreviewItem;
import com.mhtextractor.model.ThumbnailData;
import com.mhtextractor.uiport.*;

import java.io.IOException;
import java.lang.management.ManagementFactory;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

/** Backend host assembly. All model commands and callbacks run on the serial IPC host thread. */
final class IpcSession implements AutoCloseable {
    static final List<String> METHODS = List.of("importPaths", "group", "setParams", "extract",
            "workspacePage", "previewFiles", "fileInfo", "releaseFiles", "metrics", "confirmAnswer");
    static final List<String> STRUCTURE_METHODS = List.of(
            "ungroup", "renameGroup", "toggleGroupExpanded", "clearItems", "applyDrop", "removeItems", "removeGroup", "canUndo");
    static final List<String> ACTIVITY_METHODS = List.of("cancelWorkspaceActivity", "cancelPreviewLoad",
            "startPreparse", "startPreparseFor", "refreshPreparseProgress", "loadPreview",
            "resolvePreviewRegion", "awaitPreviewInFlight", "applyImportPlan",
            "activityGeneration", "previewGeneration", "previewLoadingPath");
    static final List<String> PARAM_METHODS = List.of("setGlobalParams", "setGroupParams", "setItemParams",
            "clearParams", "applyGlobalParams", "undo", "runtimeConfig", "outputUnitPlan", "paramSchema");
    static final List<String> EXTRACTION_METHODS = List.of("startExtraction", "cancelExtraction");
    private final ObjectMapper json;
    private final WorkspaceModel model = new WorkspaceModel();
    private final GlobalParameterCache global = new GlobalParameterCache();
    private final ArrayBlockingQueue<Runnable> callbacks = new ArrayBlockingQueue<>(256);
    private final Thread host = Thread.currentThread();
    private final IpcFiles files;
    private final PreviewSession previews;
    private final PreviewService previewService;
    private final WorkspaceExtractionCoordinator extractions;
    private final IpcConfirmations confirmations;
    final Uiport port;
    private Consumer<ObjectNode> events;
    private boolean importDone;
    private boolean importFailed;
    private PortEvent.ExtractionTerminal terminal;
    private boolean imageMode;
    private String outputFolder;
    private int progressBucket = -1;
    private long rawProgress;
    private long sentProgress;
    private volatile int queuePeak;
    private volatile boolean closing;
    private volatile boolean disconnecting;
    private boolean importing;
    private boolean applyingPlan;
    private boolean activityImageMode;
    private final java.util.Set<Thread> workers = java.util.concurrent.ConcurrentHashMap.newKeySet();
    private final java.util.List<String> importChanges = new java.util.ArrayList<>();
    private final java.util.Map<Long, PreviewService.Prepared> previewInputs = new java.util.HashMap<>();
    private final java.util.Map<Long, java.util.List<PortEvent.PreviewNotice>> pendingNotices = new java.util.HashMap<>();
    private final IpcWorkspaceCodec codec;
    private final IpcParamCodec paramCodec;
    private Runnable inputPump = () -> { };
    private Runnable silentChange = () -> { };
    private ExtractionPlanService extractionPlans;
    private boolean synchronousExtraction;

    IpcSession(ObjectMapper json) throws IOException {
        this.json = json;
        confirmations = new IpcConfirmations(json, this::dispatch, data -> emit("confirmationRequested", data),
                data -> emit("confirmationExpired", data));
        files = new IpcFiles(json);
        codec = new IpcWorkspaceCodec(json, files);
        paramCodec = new IpcParamCodec(json);
        previews = PreviewSession.create(files.root.resolve("preview-cache"));
        previewService = new PreviewService(previews.lifecycle());
        var plans = new ExtractionPlanService(new ExtractionPlanService.Context() {
            public List<Object> dataOrder() { return model.topLevel(); }
            public boolean imageMode() { return imageMode; }
            public AppConfig textParamsCache() { return global.text(); }
            public AppConfig imageParamsCache() { return global.image(); }
            public String inputFolder() { return null; }
            public String outputFolder() { return outputFolder; }
            public boolean openFolderAfterComplete() { return false; }
        });
        Confirmer confirmer = confirmations;
        var activities = new WorkspaceActivityService(new WorkspaceActivityService.Context() {
            public List<PreviewItem> items() { return model.allItems(); }
            public boolean textMode() { return !activityImageMode; }
            public AppConfig effectiveParams(PreviewItem item) { return params(item, activityImageMode); }
            public AppConfig effectiveImageParams(PreviewItem item) { return params(item, true); }
        }, previewService, IpcImages::thumbnail, this::dispatch);
        var clipboard = new ParamClipboard(model::push, target -> ParamScope.GLOBAL, (target, mode, config) -> { });
        var paramCommands = new WorkspaceParamCommandService(model, new WorkspaceParamService(previews.lifecycle()),
                global, clipboard::pushParamUndo);
        // A server import round is bounded to 20k inputs; continuing requires a client decision.
        var imports = new WorkspaceImportCoordinator(model, confirmer, this::dispatch, 200, 20000);
        extractionPlans = plans;
        extractions = new WorkspaceExtractionCoordinator(new WorkspaceExtractionService(previews.lifecycle()),
                checked -> WorkspaceExtractionCoordinator.productionRequests(extractionPlans,
                        () -> model.allItems().stream().filter(item -> !item.removed).toList(), confirmer).apply(checked), this::dispatch);
        port = new InProcessUiport(model, confirmer, plans, activities, paramCommands, imports, extractions,
                new WorkspaceParamService(previews.lifecycle()));
        port.events().subscribe(this::onEvent);
    }

    void events(Consumer<ObjectNode> sink) { events = sink; }

    IpcFiles files() { return files; }

    void silentChanges(Runnable changed) { silentChange = changed; }

    void drainCallbacks() {
        for (int i = 0; i < 256; i++) {
            var callback = callbacks.poll();
            if (callback == null) return;
            callback.run();
        }
    }

    void inputPump(Runnable pump) { inputPump = pump; }

    void disconnect() {
        if (disconnecting) return;
        disconnecting = true;
        try {
            // Mark the run cancelled before waking its confirmation waiter; otherwise it may win a natural-completion race.
            port.commands().cancelExtraction();
        } finally {
            confirmations.disconnect(); // Also release import confirmations, even if terminal delivery broke stdout.
            if (port.queries().previewLoadingPath() != null
                    || workers.stream().anyMatch(t -> t.isAlive() && t.getName().equals("preview-preparse")))
                port.commands().cancelWorkspaceActivity();
        }
    }

    private AppConfig params(PreviewItem item, boolean mode) {
        AppConfig config = ParamScope.effectiveParams(item.parentGroup, item.textItemParams,
                item.imageItemParams, mode, global.text(), global.image());
        return config == null ? new AppConfig() : config;
    }

    private void dispatch(Runnable callback) {
        if (closing) return;
        if (Thread.currentThread() == host) { callback.run(); return; }
        String workerName = Thread.currentThread().getName();
        if (workerName.startsWith("preview-") || workerName.startsWith("mht-import-") || workerName.startsWith("extraction-"))
            workers.add(Thread.currentThread());
        boolean interrupted = false;
        try {
            while (!closing) {
                try {
                    if (callbacks.offer(callback, 25, TimeUnit.MILLISECONDS)) break;
                } catch (InterruptedException e) { interrupted = true; }
            }
            queuePeak = Math.max(queuePeak, callbacks.size());
        } finally {
            if (interrupted) Thread.currentThread().interrupt();
        }
    }

    private void start(Runnable command) {
        var before = Thread.getAllStackTraces().keySet();
        command.run();
        // Existing app coordinators create these workers synchronously before returning.
        // Keep their handles so shutdown also joins a parser that has not delivered a callback yet.
        Thread.getAllStackTraces().keySet().stream().filter(t -> !before.contains(t))
                .filter(t -> t.getName().equals("preview-preparse") || t.getName().equals("preview-image-load")
                        || t.getName().equals("mht-import-scan")).forEach(workers::add);
    }

    boolean busy() { return extractions.running.get() || importing || !pendingNotices.isEmpty() || port.queries().previewLoadingPath() != null
            || workers.stream().anyMatch(t -> t.isAlive() && t.getName().equals("preview-preparse")); }

    private void await(java.util.function.BooleanSupplier done) throws InterruptedException {
        // Synchronous methods finish their activity before responding; no worker touches the model afterward.
        while (!done.getAsBoolean()) {
            inputPump.run();
            Runnable callback = callbacks.poll(25, TimeUnit.MILLISECONDS);
            if (callback != null) callback.run();
        }
    }

    private void emit(String name, ObjectNode data) {
        ObjectNode frame = json.createObjectNode().put("v", 1).put("type", "event").put("event", name);
        frame.set("data", data);
        events.accept(frame);
    }

    private void onEvent(PortEvent event) {
        try { encodeEvent(event); }
        catch (IOException e) { throw new java.io.UncheckedIOException(e); }
    }

    private void encodeEvent(PortEvent event) throws IOException {
        switch (event) {
            case PortEvent.WorkspaceActivityChanged changed -> emit("workspaceActivityChanged", generation(changed.generation()));
            case PortEvent.PreparseStarted started -> emit("preparseStarted", generation(started.generation()));
            case PortEvent.PreparseProgress progress -> emit("preparseProgress", generation(progress.generation())
                    .put("done", progress.done()).put("total", progress.total()));
            case PortEvent.PreparseFinished finished -> {
                var result = finished.result();
                var value = json.createObjectNode().put("path", result.path()).put("status", result.status().name())
                        .put("errorKey", result.errorKey()).put("errorDetail", result.errorDetail())
                        .put("text", result.text()).put("textAssigned", result.textAssigned())
                        .put("title", result.title()).put("titleAssigned", result.titleAssigned());
                emit("preparseFinished", generation(finished.generation()).set("result", codec.file(value)));
            }
            case PortEvent.WorkspaceChanged changed -> {
                if (importing || applyingPlan) importChanges.add(changed.kind());
                else emit("workspaceChanged", json.createObjectNode().put("kind", changed.kind()));
            }
            case PortEvent.ImportStateChanged state -> {
                importing = state.importing();
                if (!importing) flushImportChanges();
                emit("importStateChanged", generation(state.generation()).put("importing", state.importing()));
            }
            case PortEvent.ImportRound round -> {
                flushImportChanges();
                var groups = json.createArrayNode();
                var snapshot = port.queries().workspace();
                for (var group : round.createdGroups()) groups.add(codec.group(snapshot.groups().stream()
                        .filter(vm -> vm.no() == group.getGroupNo()).findFirst().orElseThrow()));
                var data = generation(round.generation()).put("newFiles", round.newFiles()).put("newGroups", round.newGroups())
                        .put("madeListNonEmpty", round.madeListNonEmpty());
                data.set("plan", codec.file(codec.plan(round.plan())));
                data.set("createdGroups", codec.file(groups));
                emit("importRound", data);
            }
            case PortEvent.ImportFinished finished -> {
                importDone = true;
                emit("importFinished", generation(finished.generation())
                        .put("count", finished.accumulatedPaths().size()).put("failed", importFailed)
                        .set("accumulatedPaths", codec.file(json.valueToTree(finished.accumulatedPaths()))));
            }
            case PortEvent.Notice notice -> {
                importFailed = true;
                emit("notice", json.createObjectNode().put("key", notice.key()).put("level", notice.level().name())
                        .set("namedParams", json.valueToTree(notice.namedParams())));
            }
            case PortEvent.PreviewLoadStateChanged state -> {
                if (state.active()) {
                    var item = item(state.path());
                    previewInputs.put(state.generation(), previewService.prepare(Path.of(state.path()), params(item, activityImageMode)));
                }
                emit("previewLoadStateChanged", generation(state.generation()).put("path", state.path()).put("active", state.active()));
            }
            case PortEvent.PreviewConfirmationRequired required -> emit("previewConfirmationRequired", json.createObjectNode()
                    .put("path", required.path()).put("name", required.name()).put("sizeMiB", required.sizeMiB()));
            case PortEvent.PreviewLoadFailed failed -> {
                previewInputs.remove(failed.generation());
                emit("previewLoadFailed", generation(failed.generation()).put("path", failed.path())
                        .put("fileInfo", failed.fileInfo()).put("detail", failed.detail()));
            }
            case PortEvent.PreviewThumbnail thumbnail -> {
                var prepared = previewInputs.get(thumbnail.generation());
                if (prepared == null) throw new IOException("Missing preview input");
                var meta = previews.store().load(prepared.cacheKey()).orElseThrow(() -> new IOException("Missing preview cache"));
                var data = image(meta, thumbnail.index(), thumbnail.thumbnail());
                data.put("generation", thumbnail.generation()).put("path", thumbnail.path()).put("index", thumbnail.index());
                emit("previewThumbnail", data);
            }
            case PortEvent.PreviewLoaded loaded -> {
                var data = generation(loaded.generation()).put("path", loaded.path());
                var item = item(loaded.path());
                if (item.cachedMeta != null && loaded.generation() == port.queries().previewGeneration()) {
                    exportLoaded(loaded, item, data);
                } else {
                    data.putNull("manifest");
                    emit("previewLoaded", data);
                }
                previewInputs.remove(loaded.generation());
            }
            case PortEvent.PreviewRegionConfirmationRequired required -> emit("previewRegionConfirmationRequired",
                    generation(required.generation()).put("path", required.path()));
            case PortEvent.PreviewNotice notice -> {
                if (pendingNotices.containsKey(notice.generation())) {
                    pendingNotices.get(notice.generation()).add(notice);
                    return;
                }
                var args = json.createObjectNode();
                var meta = item(notice.path()).cachedMeta;
                if (meta != null) meta.warnings().stream().filter(w -> w.key().equals(notice.key()))
                        .findFirst().ifPresent(w -> w.args().forEach(args::put));
                emit("previewNotice", generation(notice.generation()).put("path", notice.path()).put("key", notice.key())
                        .set("namedParams", args));
            }
            case PortEvent.ParamStateChanged changed -> {
                // The GUI host already resets derived preview state after parameter events.
                // This host must also discard in-memory references to invalidated cache files.
                var affected = new java.util.HashSet<>(changed.affectedPaths());
                for (var item : model.allItems()) if (affected.contains(item.path)) item.resetPreviewState();
                emit("paramsChanged", json.createObjectNode()
                        .put("kind", changed.kind().name()).put("affectedCount", changed.affectedPaths().size())
                        .put("imageMode", changed.imageMode())
                        .set("affectedPaths", codec.file(json.valueToTree(changed.affectedPaths()))));
            }
            case PortEvent.ExtractionProgress progress -> {
                rawProgress++;
                int bucket = (int) (Math.clamp(progress.overall(), 0, 1) * 100);
                if (!synchronousExtraction || bucket > progressBucket) {
                    progressBucket = bucket;
                    sentProgress++;
                    emit("extractionProgress", json.createObjectNode().put("generation", progress.generation())
                            .put("overall", progress.overall()));
                }
            }
            case PortEvent.ExtractionTerminal end -> {
                terminal = end;
                var data = terminalSummary(end);
                data.put("sessionOutputFolder", end.sessionOutputFolder());
                data.set("stats", end.stats() == null ? json.nullNode() : codec.file(stats(end.stats())));
                emit("extractionTerminal", data);
            }
            case PortEvent.ExtractionResult result -> emit("extractionResult", generation(result.generation())
                    .put("sessionOutputFolder", result.sessionOutputFolder())
                    .set("stats", codec.file(stats(result.stats()))));
            case PortEvent.RunningChanged changed -> emit("runningChanged", generation(changed.generation())
                    .put("running", changed.running()));
            default -> { } // Never send thumbnail pixels.
        }
    }

    private ObjectNode generation(long value) { return json.createObjectNode().put("generation", value); }

    /** Explicit full DTO encoding also works in native without registering record reflection. */
    private ObjectNode stats(ExtractionStats stats) {
        var value = json.createObjectNode().put("summaryLine", stats.summaryLine()).put("failCount", stats.failCount())
                .put("skipCount", stats.skipCount()).put("warnCount", stats.warnCount());
        var outcomes = value.putArray("files");
        for (var outcome : stats.files()) {
            var file = outcomes.addObject().put("path", outcome.path()).put("outcome", outcome.outcome().name())
                    .put("message", outcome.message());
            var warnings = file.putArray("warnings");
            for (var warning : outcome.warnings()) {
                var entry = warnings.addObject().put("key", warning.key());
                var args = entry.putObject("args");
                warning.args().forEach(args::put);
            }
        }
        return value;
    }

            case "cancelPreviewLoad" -> {
                long old = port.queries().previewGeneration();
                boolean hadLoad = port.queries().previewLoadingPath() != null;
                port.commands().cancelPreviewLoad();
                if (!hadLoad && old != port.queries().previewGeneration()) silentChange.run();
                return json.nullNode();
            }
            case "startPreparse", "startPreparseFor" -> {
                List<String> targets = method.equals("startPreparseFor") ? paths(p, "paths", null, false)
                        : model.allItems().stream().filter(it -> !it.removed).map(it -> it.path).toList();
                for (String path : targets) IpcFiles.input(path);
                boolean mode = runtime(p);
                activityImageMode = mode;
                start(() -> {
                    if (method.equals("startPreparse")) port.commands().startPreparse();
                    else port.commands().startPreparseFor(targets);
                });
                return json.nullNode();
            }
            case "refreshPreparseProgress" -> { port.commands().refreshPreparseProgress(); return json.nullNode(); }
            case "loadPreview" -> {
                String path = string(p, "path");
                boolean confirmed = bool(p, "largeFileConfirmed");
                boolean mode = runtime(p);
                if (item(path).removed) throw new IllegalArgumentException("Removed preview item");
                IpcFiles.input(path);
                activityImageMode = mode;
                start(() -> port.commands().loadPreview(path, confirmed));
                return json.nullNode();
            }
            case "resolvePreviewRegion" -> {
                long generation = integer(p, "generation");
                String path = string(p, "path");
                boolean accepted = bool(p, "accepted");
                IpcFiles.input(path);
                start(() -> port.commands().resolvePreviewRegion(generation, path, accepted));
                return json.nullNode();
            }
            case "awaitPreviewInFlight" -> {
                long millis = integer(p, "millis");
                long duration = TimeUnit.MILLISECONDS.toNanos(millis);
                long started = System.nanoTime();
                do {
                    inputPump.run();
                    drainCallbacks();
                    // Short joins retain the port's worker/cleanup semantics without starving input or delivery.
                    port.commands().awaitPreviewInFlight(Math.min(5, millis));
                    if (workers.stream().noneMatch(t -> t.isAlive() && t.getName().startsWith("preview-"))) break;
                } while (System.nanoTime() - started < duration && !disconnecting);
                drainCallbacks();
                return json.nullNode();
            }
            case "activityGeneration" -> { return generation(port.queries().activityGeneration()); }
            case "previewGeneration" -> { return generation(port.queries().previewGeneration()); }
            case "previewLoadingPath" -> { return json.createObjectNode().put("path", port.queries().previewLoadingPath()); }
            case "applyImportPlan" -> {
                if (importing) throw new IllegalArgumentException("Import already active");
                ImportPlanVm plan = plan(files.readUpload(p.path("plan")));
                applyingPlan = true;
                try { port.commands().applyImportPlan(plan); }
                finally { applyingPlan = false; flushImportChanges(); }
                return json.nullNode();
            }
            case "confirmAnswer" -> {
                String id = string(p, "confirmationId");
                JsonNode action = p.get("actionKey");
                if (action == null || (!action.isNull() && !action.isTextual())) {
                    throw new IllegalArgumentException("actionKey string or null required");
                }
                return json.createObjectNode().put("accepted", confirmations.answer(id, action.isNull() ? null : action.asText()));
            }
            case "importPaths" -> {
                List<String> paths = paths(p, "paths", "pathsFile", false);
                if (paths.isEmpty() || importing) throw new IllegalArgumentException("Nonempty paths and idle importer required");
                if (p.has("sourceDesc") && !p.path("sourceDesc").isTextual()) throw new IllegalArgumentException("sourceDesc string required");
                String source = p.has("sourceDesc") ? p.path("sourceDesc").textValue() : "IPC";
                boolean fromDrag = p.has("fromDrag") && bool(p, "fromDrag");
                boolean async = p.has("async") && bool(p, "async");
                for (String path : paths) IpcFiles.input(path);
                importDone = false;
                importFailed = false;
                start(() -> port.commands().importPaths(paths, source, fromDrag));
                if (async) return json.nullNode();
                await(() -> importDone && !importing);
                return json.createObjectNode().put("count", model.allItems().size()).put("failed", importFailed);
            }
            case "group" -> {
                List<String> paths = paths(p, "paths", "pathsFile", false);
                String prefix = string(p, "namePrefix");
                port.commands().group(paths, prefix);
                return json.nullNode();
            }
            case "ungroup", "renameGroup", "toggleGroupExpanded", "removeGroup" -> {
                long no = integer(p, "groupNo");
                switch (method) {
                    case "ungroup" -> port.commands().ungroup(no);
                    case "renameGroup" -> {
                        if (!p.path("newName").isTextual()) throw new IllegalArgumentException("newName string required");
                        port.commands().renameGroup(no, p.path("newName").textValue());
                    }
                    case "toggleGroupExpanded" -> port.commands().toggleGroupExpanded(no);
                    case "removeGroup" -> port.commands().removeGroup(no);
                }
                return json.nullNode();
            }
            case "clearItems" -> { port.commands().clearItems(); return json.nullNode(); }
            case "removeItems" -> {
                port.commands().removeItems(paths(p, "paths", null, false));
                return json.nullNode();
            }
            case "canUndo" -> {
                return json.createObjectNode().put("canUndo", port.queries().canUndo())
                        .put("undoDepth", port.queries().workspace().undoDepth());
            }
            case "applyDrop" -> {
                // A parent change can start a parser; revalidate before any structure mutation.
                for (var item : model.allItems()) if (!item.removed) IpcFiles.input(item.path);
                var drop = port.commands().applyDrop(target(p.get("dragged"), false),
                        target(p.get("target"), true), string(p, "zone"));
                var affected = json.createArrayNode();
                drop.affectedPaths().forEach(affected::add);
                var result = json.createObjectNode().put("changed", drop.changed());
                result.set("affectedPaths", files.write(".json", json.writeValueAsBytes(affected), "application/json"));
                return result;
            }
            case "setParams" -> {
                boolean mode = bool(p, "imageMode");
                if (!p.path("config").isObject()) throw new IllegalArgumentException("config object required");
                AppConfig config = json.treeToValue(p.path("config"), AppConfig.class);
                port.commands().setGlobalParams(mode, config);
                imageMode = mode;
                return json.nullNode();
            }
            case "extract" -> {
                boolean checked = bool(p, "checkedOnly");
                String out = string(p, "outputFolder");
                startExtraction(checked, null, true, out);
                await(() -> terminal != null);
                var result = terminalSummary(terminal);
                if (terminal.stats() != null) {
                    var outcomes = json.createArrayNode();
                    for (var outcome : terminal.stats().files()) outcomes.addObject().put("path", outcome.path())
                            .put("outcome", outcome.outcome().name()).put("message", outcome.message());
                    result.set("resultsFile", files.write(".json", json.writeValueAsBytes(outcomes), "application/json"));
                }
                // Use the lifecycle's batch deletion for completed inputs (same deletion semantics as rule b).
                if (terminal.end() != PortEvent.ExtractionEnd.CANCELLED)
                    previews.lifecycle().onItemsRemoved(model.allItems().stream().map(item -> item.path).toList());
                return result;
            }
            case "startExtraction" -> {
                boolean checked = bool(p, "checkedOnly");
                var plans = requestPlans(p);
                startExtraction(checked, plans, false, string(p.path("runtime"), "outputFolder"));
                return json.nullNode();
            }
            case "cancelExtraction" -> {
                port.commands().cancelExtraction();
                return json.nullNode();
            }
            case "previewFiles" -> { return preview(p); }
            case "fileInfo" -> {
                Path path = files.validateIssued(string(p, "path"));
                return files.issue(path, "application/octet-stream");
            }
            case "releaseFiles" -> {
                List<String> paths = strings(p, "paths");
                for (String path : paths) files.validateIssued(path); // Atomic validation before deletion.
                for (String path : paths.stream().distinct().toList()) files.release(path);
                return json.nullNode();
            }
            case "metrics" -> {
                long peak = ManagementFactory.getMemoryPoolMXBeans().stream()
                        .filter(pool -> pool.getType() == java.lang.management.MemoryType.HEAP)
                        .mapToLong(pool -> Math.max(0, pool.getPeakUsage().getUsed())).sum();
                return json.createObjectNode().put("heapPoolPeakBytes", peak).put("callbackQueuePeak", queuePeak)
                        .put("callbackQueueSize", callbacks.size()).put("activityWorkers", workers.stream().filter(Thread::isAlive).count())
                        .put("rawProgress", rawProgress).put("sentProgress", sentProgress);
            }
            default -> throw new IllegalArgumentException("Unknown extension method");
        }
    }

    private ObjectNode preview(JsonNode p) throws Exception {
        if (p.has("pngThumbnails")) {
            if (!p.path("pngThumbnails").isBoolean() || p.path("pngThumbnails").booleanValue())
                throw new IllegalArgumentException("PNG transcoding is not supported; use real encoded image files");
        }
        String id = string(p, "path");
        PreviewItem item = model.allItems().stream().filter(it -> it.path.equals(id) && !it.removed).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("Preview requires an imported item id"));
        Path source = IpcFiles.input(id);
        var text = SourceParseService.parse(id, params(item, false), true);
        var parsed = SourceParsers.forPath(id).parse(id, true, () -> false, null, null);
        var result = previewService.ensureCachedLocked(previewService.prepare(source, params(item, true)), () -> false);
        ObjectNode manifest = json.createObjectNode();
        manifest.set("text", files.write(".txt", (text.text() == null ? "" : text.text()).getBytes(StandardCharsets.UTF_8), "text/plain; charset=utf-8"));
        manifest.set("html", files.write(".html", (parsed.getHtmlContent() == null ? "" : parsed.getHtmlContent())
                .getBytes(StandardCharsets.UTF_8), "text/html; charset=utf-8"));
        var thumbs = manifest.putArray("thumbnails");
        for (int i = 0; i < result.images().size(); i++) {
            Path image = previews.store().imageFileFor(result.meta(), i);
            byte[] bytes = Files.readAllBytes(image);
            String ext = IpcImages.extension(bytes);
            var metadata = IpcImages.thumbnail(new PreviewImageData(result.images().get(i).originalName(),
                    result.images().get(i).sourceId(), bytes), i, params(item, true));
            ObjectNode ref = files.borrowImage(image, IpcImages.mediaType(ext));
            ref.put("name", result.thumbs().get(i).coreName()).put("index", i).put("imagePath", image.toString())
                    .put("coreName", metadata.coreName()).put("width", metadata.width()).put("height", metadata.height()).put("extension", ext);
            thumbs.add(ref); // Encoded original: client decodes/scales, never ARGB/base64 over stdio.
        }
        return json.createObjectNode().put("imageCount", thumbs.size())
                .set("manifest", files.write(".json", json.writeValueAsBytes(manifest), "application/json"));
    }

    /** Both IPC paths launch the existing port channel; only the script wrapper waits. */
    private void startExtraction(boolean checked, ExtractionPlanService plans, boolean synchronous, String output) throws IOException {
        if (extractions.running.get()) throw new IllegalArgumentException("Extraction already running");
        if (model.allItems().stream().noneMatch(item -> !item.removed && (!checked || item.selected)))
            throw new IllegalArgumentException("No extraction targets");
        // Revalidate imported ids immediately before the parser opens them.
        for (PreviewItem item : model.allItems()) if (!item.removed) IpcFiles.input(item.path);
        String checkedOutput = IpcFiles.output(output).toString();
        if (synchronous) outputFolder = checkedOutput;
        terminal = null;
        progressBucket = -1;
        synchronousExtraction = synchronous;
        var previous = extractionPlans;
        if (plans != null) extractionPlans = plans;
        var before = Thread.getAllStackTraces().keySet();
        try { port.commands().startExtraction(checked); }
        finally {
            extractionPlans = previous;
            // The existing coordinator starts an unnamed worker before returning.
            Thread.getAllStackTraces().keySet().stream().filter(t -> !before.contains(t) && !t.isDaemon())
                    .forEach(workers::add);
        }
    }

    private boolean runtime(JsonNode p) throws IOException {
                    var snapshot = snapshot();
                    if (params.path("bulk").asBoolean()) {
                        var bulk = json.createObjectNode().put("revision", revision);
                        bulk.set("manifest", codec.file(snapshot));
                        result = bulk;
                    } else result = snapshot;
                }
                case "setChecked" -> {
                    if (!params.path("checked").isBoolean()) {
                        return error(id, "INVALID_PARAMS", "setChecked requires paths array and boolean checked");
                    }
                    // Validate the entire array before invoking a mutating command.
                    var paths = new ArrayList<String>();
                    if (params.has("paths") == params.has("pathsFile")) throw new IllegalArgumentException("Exactly one paths source required");
                    var values = params.has("pathsFile") ? files.readUpload(params.path("pathsFile")) : params.path("paths");
                    if (!values.isArray()) throw new IllegalArgumentException("Paths array required");
                    for (JsonNode path : values) {
                        if (!path.isTextual() && !path.isNull()) {
                            return error(id, "INVALID_PARAMS", "paths entries must be strings or null");
                        }
                        paths.add(path.isNull() ? null : path.textValue());
                        if (params.has("pathsFile") && !path.isNull()) IpcFiles.input(path.textValue());
                    }
                    port.commands().setChecked(paths, params.path("checked").booleanValue());
                    result = json.nullNode();
                }
                default -> {
                    String method = request.path("method").asText();
                    if (session == null || (!IpcSession.METHODS.contains(method) && !IpcSession.STRUCTURE_METHODS.contains(method)
                            && !IpcSession.ACTIVITY_METHODS.contains(method) && !IpcSession.PARAM_METHODS.contains(method)
                            && !IpcSession.EXTRACTION_METHODS.contains(method))) {
                        return error(id, "UNKNOWN_METHOD", "Unknown method: " + method);
                    }
                    if (method.equals("workspacePage")) result = page(params);
                    else {
                        if (method.equals("applyDrop") && IpcSession.integer(params, "revision") != revision) {
                            throw new IllegalArgumentException("Stale revision");
                        }
                        result = session.call(method, params);
                        if (method.equals("releaseFiles")) {
                            currentSnapshot = null;
                            pageSnapshot = null;
                        }
                        if (result.isObject() && (method.equals("applyDrop") || method.equals("canUndo")
                                || java.util.List.of("activityGeneration", "previewGeneration", "previewLoadingPath",
                                        "runtimeConfig", "outputUnitPlan", "paramSchema").contains(method))) {
                            ((ObjectNode) result).put("revision", revision);
                        }
                    }
                }
            }
            ObjectNode response = frame("response").put("id", id);
            response.put("revision", revision);
            response.set("result", result);
            return response;
        } catch (UncheckedIOException e) {
            throw e;
        } catch (IllegalArgumentException | JsonProcessingException | java.nio.file.NoSuchFileException e) {
            return error(id, "INVALID_PARAMS", "Invalid method parameters");
        } catch (Exception e) {
            log.error("IPC request failed: id={}", id, e);
            return error(id, "INTERNAL_ERROR", "Request failed; see backend log");
        }
    }

    private ObjectNode hello(String id, JsonNode params) {
        // A failed repeat handshake revokes the previous agreement as well.
        welcomed = false;
        if (!params.path("protocolVersion").isIntegralNumber()
                || !params.path("protocolVersion").canConvertToInt()
                || params.path("protocolVersion").intValue() < 1
                || !params.path("version").isTextual() || params.path("version").asText().isBlank()
                || !params.path("buildId").isTextual() || params.path("buildId").asText().isBlank()) {
            return error(id, "INVALID_PARAMS", "hello requires positive integer protocolVersion and nonempty version/buildId");
        }
        BackendIdentity expected = new BackendIdentity(params.path("protocolVersion").intValue(),
                params.path("version").asText(), params.path("buildId").asText());
        String mismatch = expected.mismatch(identity);
        if (mismatch != null) return error(id, "HANDSHAKE_FAILED", mismatch);
        ObjectNode response = frame("response").put("id", id);
        ObjectNode welcome = response.putObject("result").put("kind", "welcome")
                .put("protocolVersion", identity.protocolVersion()).put("version", identity.version())
                .put("buildId", identity.buildId());
        ArrayNode capabilities = welcome.putArray("capabilities").add("workspace").add("setChecked");
        if (session != null) capabilities.add("workspacePage").add("bulkFiles").add("confirmationRoundTrip");
        if (session != null) IpcSession.EXTRACTION_METHODS.forEach(capabilities::add);
        welcome.put("confirmationRoundTrip", session != null);
        welcome.put("sessionId", sessionId).put("bulkRoot", files.root.toString());
        response.put("revision", revision);
        welcomed = true;
        return response;
    }

