                .put("outputFolder", end.sessionOutputFolder());
        if (end.stats() != null) summary.put("count", end.stats().files().size()).put("failCount", end.stats().failCount())
                .put("skipCount", end.stats().skipCount()).put("warnCount", end.stats().warnCount());
        return summary;
